1	use std::{
2	    collections::HashMap,
3	    path::{Path, PathBuf},
4	    sync::OnceLock,
5	};
6	
7	use crate::{
8	    Error, Match, PartialErrorBuilder, dir::Ignore, pathutil::is_hidden_path,
9	};
10	
11	/// A cached matcher for checking paths against hierarchical ignore files.
12	///
13	/// An `IncrementalIgnore` is built from a [`crate::WalkBuilder`]. Unlike a
14	/// recursive walk, it can check individual paths while still respecting the
15	/// ignore files in every relevant parent directory. Matchers for directories
16	/// are compiled on first use and then retained for later queries.
17	/// Each matcher corresponds to exactly one root configured on the builder,
18	/// and paths passed to it are interpreted relative to that root.
19	/// A matcher for the special `-` root representing standard input is inert
20	/// and always returns a non-match.
21	///
22	/// The matcher checks path-based filters in the same precedence order as
23	/// a traversal. This includes glob overrides, `.ignore`, `.gitignore`,
24	/// `.git/info/exclude`, global and explicitly added ignore files, custom
25	/// ignore file names and file type selections. It does not apply filters that
26	/// require a directory entry or other traversal state, such as custom entry
27	/// predicates. Hidden-file detection, minimum and maximum depth limits and the
28	/// maximum file size are applied.
29	///
30	/// A matcher is a snapshot at directory granularity. Once the ignore files in
31	/// a directory have been loaded, edits to those files are not observed. Call
32	/// [`IncrementalIgnore::refresh`] to reload them, or build a new matcher.
33	///
34	/// # Warning
35	///
36	/// The incremental path checking here necessarily needs to do a lot more work
37	/// per path matched. Callers should _not_ use this to run directory traversal.
38	/// This is intended to avoid the work of re-traversing an entire directory
39	/// tree when only a few changes are detected. (For example, in response to
40	/// file additions or deletions.)
41	///
42	/// # Example
43	///
44	/// ```rust,no_run
45	/// use ignore::WalkBuilder;
46	///
47	/// let mut builder = WalkBuilder::new(".");
48	/// builder.add_custom_ignore_filename(".rgignore");
49	/// let mut matchers = builder.build_matchers();
50	/// let matcher = &mut matchers[0];
51	///
52	/// if matcher.matched("src/generated.rs", false).is_ignore() {
53	///     println!("ignored");
54	/// }
55	/// ```
56	#[derive(Clone, Debug)]
57	pub struct IncrementalIgnore {
58	    /// The root exactly as it was given to `WalkBuilder`.
59	    root: PathBuf,
60	    /// The normalized root used only by the opt-in normalization routine.
61	    normalized_root: OnceLock<Option<PathBuf>>,
62	    /// The pristine root matcher from the builder.
63	    ///
64	    /// This is never used for matching directly. It is retained so that
65	    /// `refresh` can rebuild the matcher chain from disk, using a parent
66	    /// matcher cache that is not shared with other matchers built from the
67	    /// same `WalkBuilder`.
68	    base: Ignore,
69	    /// The matcher for the configured root directory, loaded on first use.
70	    ignore: RootIgnore,
71	    /// The first root matcher loaded through the parent matcher cache shared
72	    /// with sibling matchers from the same `WalkBuilder`.
73	    ///
74	    /// The shared cache holds parent directory matchers weakly, so they stay
75	    /// usable only while some matcher keeps them alive. This retains the
76	    /// chain that populated (or reused) the shared cache for as long as this
77	    /// matcher lives, even across a `refresh`, so that siblings that haven't
78	    /// queried yet keep observing the parent rules they would have seen
79	    /// without the refresh.
80	    shared_loaded: Option<Ignore>,
81	    /// Directory paths relative to `root`, excluding the root itself.
82	    dirs: HashMap<PathBuf, CachedDir>,
83	    /// Options for additional filtering beyond gitignore.
84	    options: IncrementalIgnoreOptions,
85	}
86	
87	/// The options for a matcher, mostly meant to duplicate as much as we can from
88	/// `WalkParallel`.
89	#[derive(Clone, Debug)]
90	pub(crate) struct IncrementalIgnoreOptions {
91	    pub(crate) min_depth: Option<usize>,
92	    pub(crate) max_depth: Option<usize>,
93	    pub(crate) max_filesize: Option<u64>,
94	    pub(crate) hidden: bool,
95	    pub(crate) follow_links: bool,
96	}
97	
98	#[derive(Clone, Debug)]
99	enum RootIgnore {
100	    Unloaded(Ignore),
101	    Loaded(Ignore),
102	    NotDirectory,
103	    Stdin,
104	}
105	
106	/// Cached traversal state for a directory relative to the configured root.
107	///
108	/// The presence of an entry means that the directory and every ancestor
109	/// between it and the root have already been checked.
110	#[derive(Clone, Debug)]
111	enum CachedDir {
112	    /// The directory may be descended into. The matcher includes the ignore
113	    /// rules loaded through this directory and is therefore the matcher to use
114	    /// for its children.
115	    Allowed(Ignore),
116	    /// The directory may not be descended into because it was ignored by a
117	    /// path rule or hidden-file filtering. Every descendant is consequently
118	    /// ignored, and ignore files inside this directory are not loaded.
119	    Ignored,
120	}
121	
122	impl IncrementalIgnore {
123	    pub(crate) fn new(
124	        root: PathBuf,
125	        ignore: Ignore,
126	        options: IncrementalIgnoreOptions,
127	    ) -> IncrementalIgnore {
128	        // File traversal special cases `-` to search stdin, so we recognize
129	        // it here for completeness too. In particular, we really want
130	        // `WalkBuilder::build_matchers` to return a matcher for every root,
131	        // even when it's a simple file (handled automatically) or when it's
132	        // stdin (necessarily special cased).
133	        //
134	        // If callers need to search a file or directory named `-`, then they
135	        // can use `./-`. As is the case for file traversal too.
136	        let root_ignore = if root == Path::new("-") {
137	            RootIgnore::Stdin
138	        } else {
139	            RootIgnore::Unloaded(ignore.clone())
140	        };
141	        IncrementalIgnore {
142	            root,
143	            normalized_root: OnceLock::new(),
144	            base: ignore,
145	            ignore: root_ignore,
146	            shared_loaded: None,
147	            dirs: HashMap::new(),
148	            options,
149	        }
150	    }
151	
152	    /// Return the root that paths matched by this matcher are relative to.
153	    pub fn root(&self) -> &Path {
154	        &self.root
155	    }
156	
157	    /// Reload ignore rules from disk for subsequent queries.
158	    ///
159	    /// Calling `refresh` drops every ignore rule and allow/ignore decision
160	    /// this matcher has loaded or computed so far. This covers the configured
161	    /// root, the applicable parent directories outside the root and every
162	    /// subdirectory visited by previous queries, including `.ignore`,
163	    /// `.gitignore`, `.git/info/exclude` and any configured custom ignore
164	    /// files that were added, modified or deleted, as well as the repository
165	    /// boundaries (`.git` and `.jj` directories) used to decide whether
166	    /// git-related rules apply. The first query after a refresh reads the
167	    /// rules it needs from disk again, and directories are then cached as
168	    /// usual until the next refresh.
169	    ///
170	    /// Refreshing does not traverse the directory tree and does not install
171	    /// any file system watching; directories are re-read lazily, only when a
172	    /// later query needs them. Without a call to `refresh`, the usual
173	    /// per-directory caching behavior applies and edits to ignore files are
174	    /// not observed.
175	    ///
176	    /// Only this matcher is refreshed. Other matchers built from the same
177	    /// [`crate::WalkBuilder`], and clones of this matcher made before the
178	    /// refresh, keep the rules they have already loaded. Conversely, this
179	    /// matcher reloads rules without observing or modifying the parent
180	    /// directory cache shared with those other matchers.
181	    ///
182	    /// The search root and the filtering options configured at build time are
183	    /// unaffected. In particular, global gitignore rules and explicitly added
184	    /// ignore files keep the versions loaded when this matcher was built, and
185	    /// a matcher for the special `-` root representing standard input remains
186	    /// inert.
187	    pub fn refresh(&mut self) {
188	        if matches!(self.ignore, RootIgnore::Stdin) {
189	            return;
190	        }
191	        self.dirs.clear();
192	        self.ignore = RootIgnore::Unloaded(self.base.refresh());
193	    }
194	
195	    /// Normalize `path` and return it relative to this matcher's root.
196	    ///
197	    /// This returns `None` when `path` cannot be made absolute or
198	    /// when it is known to be outside this matcher's root. Unlike
199	    /// [`IncrementalIgnore::matched`], this performs absolute path conversion,
200	    /// lexical normalization and allocation. It is intended as an opt-in
201	    /// convenience for callers that do not already have root-relative paths.
202	    ///
203	    /// Note that `.` is interpreted relative to the process level current
204	    /// working directory. It is _not_ interpreted relative to the root of
205	    /// this matcher.
206	    ///
207	    /// Note also that this may reject paths that only differ in casing. For
208	    /// example, if the root path for this matcher is `/FOO` but the provided
209	    /// path is `/foo/bar`, then this may return `None`. Callers must ensure
210	    /// casing is consistent between the path provided and the root path for
211	    /// this matcher.
212	    pub fn normalize<P: AsRef<Path>>(&self, path: P) -> Option<PathBuf> {
213	        if matches!(self.ignore, RootIgnore::Stdin) {
214	            return None;
215	        }
216	        let path = normalize_absolute(path.as_ref())?;
217	        let root = self
218	            .normalized_root
219	            .get_or_init(|| normalize_absolute(&self.root))
220	            .as_ref()?;
221	        path.strip_prefix(root).ok().map(Path::to_path_buf)
222	    }
223	
224	    /// Match a root-relative path against ignore files in its directory and
225	    /// all relevant parent directories.
226	    ///
227	    /// `is_dir` should be true when `path` should be matched as a directory.
228	    ///
229	    /// For the return value, use [`IncrementalMatch::is_ignore`],
230	    /// [`IncrementalMatch::is_whitelist`] or [`IncrementalMatch::is_none`] to
231	    /// inspect it.
232	    ///
233	    /// Matchers for previously unseen directories are loaded and cached during
234	    /// this call. Errors encountered while loading ignore files are logged. To
235	    /// receive those errors, use [`IncrementalIgnore::matched_with_errors`].
236	    ///
237	    /// `path` must be relative to this matcher's root and must not contain a
238	    /// parent directory (`..`) component. Behavior is unspecified when these
239	    /// preconditions are violated. Callers with an absolute path or with a
240	    /// path containing `.` or `..` may use [`IncrementalIgnore::normalize`]
241	    /// to get a path satisfying these preconditions. In all cases, a relative
242	    /// path is *assumed* to be relative to the root of this ignore matcher.
243	    ///
244	    /// In general, it is intended that callers doing recursive directory
245	    /// traversal on the root of this matcher may provide relative paths to
246	    /// this routine *without* calling [`IncrementalIgnore::normalize`].
247	    ///
248	    /// The empty path represents the explicitly configured root and also
249	    /// returns non-match, consistent with recursive traversal where a root is
250	    /// always treated as being at depth zero.
251	    pub fn matched<P: AsRef<Path>>(
252	        &mut self,
253	        path: P,
254	        is_dir: bool,
255	    ) -> IncrementalMatch {
256	        let (matched, err) = self.matched_with_errors(path, is_dir);
257	        if let Some(err) = err {
258	            log::debug!("error while loading ignore files: {err}");
259	        }
260	        matched
261	    }
262	
263	    /// Match a root-relative path and return errors encountered while loading
264	    /// ignore files.
265	    ///
266	    /// This is equivalent to [`IncrementalIgnore::matched`], except that
267	    /// it returns any errors from newly loaded ignore files. Loading can
268	    /// partially succeed, so valid rules are always applied to the returned
269	    /// match even when an error is present.
270	    pub fn matched_with_errors<P: AsRef<Path>>(
271	        &mut self,
272	        path: P,
273	        is_dir: bool,
274	    ) -> (IncrementalMatch, Option<Error>) {
275	        let mut errs = PartialErrorBuilder::default();
276	        let matched =
277	            self.matched_with_errors_impl(path.as_ref(), is_dir, &mut errs);
278	        (matched, errs.into_error_option())
279	    }
280	
281	    fn matched_with_errors_impl(
282	        &mut self,
283	        relative: &Path,
284	        is_dir: bool,
285	        errs: &mut PartialErrorBuilder,
286	    ) -> IncrementalMatch {
287	        // We short-circuit here when our matcher corresponds to `Stdin` in
288	        // order to always return a non-match. This is somewhat redundant with
289	        // `root_ignore()` which does this too, but we do it here so that it
290	        // always happens, e.g., before depth filtering.
291	        if relative.is_absolute() || matches!(self.ignore, RootIgnore::Stdin) {
292	            return IncrementalMatch::none(is_dir);
293	        }
294	
295	        let (mut satisfies_min, mut edge_max) = (true, false);
296	        if self.options.min_depth.is_some() || self.options.max_depth.is_some()
297	        {
298	            let depth = relative
299	                .components()
300	                .filter_map(|component| match component {
301	                    std::path::Component::CurDir => None,
302	                    component => Some(component),
303	                })
304	                .count();
305	            satisfies_min =
306	                self.options.min_depth.is_none_or(|min| depth >= min);
307	            let satisfies_max =
308	                self.options.max_depth.is_none_or(|max| depth <= max);
309	            edge_max = self.options.max_depth.is_some_and(|max| depth == max);
310	            // When we have a file that isn't past our min depth, we can give
311	            // up right away.
312	            if !is_dir && !satisfies_min {
313	                return IncrementalMatch::ignore().not_within_depth();
314	            }
315	            // Same for *anything* that exceeds our max depth.
316	            if !satisfies_max {
317	                return IncrementalMatch::ignore().not_within_depth();
318	            }
319	        }
320	
321	        // When the path is invalid in some way, we bail out early to avoid
322	        // potentially doing a stat call below.
323	        let (mut mat, valid) = self
324	            .matched_with_errors_ignore(relative, is_dir, errs)
325	            .map(|mat| (mat, true))
326	            .unwrap_or_else(|| (IncrementalMatch::none(is_dir), false));
327	
328	        if !is_dir
329	            && !mat.is_ignore()
330	            && valid
331	            && let Some(max_filesize) = self.options.max_filesize
332	        {
333	            let path = self.root().join(relative);
334	            let result = if self.options.follow_links {
335	                path.metadata()
336	            } else {
337	                path.symlink_metadata()
338	            };
339	            match result {
340	                Ok(md) if md.len() > max_filesize => {
341	                    return IncrementalMatch::ignore();
342	                }
343	                Ok(_) => {}
344	                Err(err) => {
345	                    // Record the error but otherwise fall through
346	                    let err = Error::from(err);
347	                    errs.push(err.with_path(path));
348	                }
349	            }
350	        }
351	
352	        // We still need to tag our `mat` if it doesn't pass the depth filter,
353	        // or if it's a directory on the edge of a depth filter. This can only
354	        // happen when the path is reported as a directory. Otherwise regular
355	        // files are always handled above.
356	        if is_dir {
357	            if !satisfies_min {
358	                mat = mat.not_within_depth();
359	            }
360	            if edge_max {
361	                mat = mat.no_descent();
362	            }
363	        }
364	        mat
365	    }
366	
367	    fn matched_with_errors_ignore(
368	        &mut self,
369	        relative: &Path,
370	        is_dir: bool,
371	        errs: &mut PartialErrorBuilder,
372	    ) -> Option<IncrementalMatch> {
373	        let mut components = relative
374	            .components()
375	            .filter_map(|component| match component {
376	                std::path::Component::CurDir => None,
377	                component => Some(component),
378	            })
379	            .peekable();
380	        components.peek()?;
381	
382	        // If the exact parent is cached, then all of its ancestors have
383	        // already been checked. An allowed cache entry is the matcher to use
384	        // for children of that directory, while an ignored cache entry is
385	        // terminal for every descendant. In the usual case, this avoids both
386	        // walking every component and allocating a relative directory path.
387	        //
388	        // Only try the fast path when the final component is a normal path
389	        // component. Invalid paths are handled by the component walk below.
390	        let has_normal_final_component =
391	            relative.components().next_back().is_some_and(|component| {
392	                matches!(component, std::path::Component::Normal(_))
393	            });
394	        if has_normal_final_component && let Some(parent) = relative.parent() {
395	            match self.dirs.get(parent) {
396	                Some(CachedDir::Allowed(ignore)) => {
397	                    return Some(self.match_path(ignore, relative, is_dir));
398	                }
399	                Some(CachedDir::Ignored) => {
400	                    return Some(IncrementalMatch::ignore());
401	                }
402	                None => {}
403	            }
404	        }
405	
406	        let mut ignore = self.root_ignore(errs)?;
407	        let mut dir = PathBuf::new();
408	        while let Some(component) = components.next() {
409	            match component {
410	                std::path::Component::ParentDir
411	                | std::path::Component::RootDir
412	                | std::path::Component::Prefix(_) => {
413	                    return None;
414	                }
415	                std::path::Component::CurDir => continue,
416	                std::path::Component::Normal(_) => {}
417	            }
418	            if components.peek().is_none() {
419	                break;
420	            }
421	            dir.push(component.as_os_str());
422	            match self.dirs.get(&dir) {
423	                Some(CachedDir::Allowed(cached)) => {
424	                    ignore = cached.clone();
425	                    continue;
426	                }
427	                Some(CachedDir::Ignored) => {
428	                    return Some(IncrementalMatch::ignore());
429	                }
430	                None => {}
431	            }
432	
433	            let path = self.root.join(&dir);
434	            let mat = ignore.matched(&path, true);
435	            let is_hidden =
436	                self.options.hidden && mat.is_none() && is_hidden_path(&path);
437	            if mat.is_ignore() || is_hidden {
438	                self.dirs.insert(dir.clone(), CachedDir::Ignored);
439	                return Some(IncrementalMatch::ignore());
440	            }
441	            let (child, err) = ignore.add_child(&path);
442	            errs.maybe_push(err);
443	            self.dirs.insert(dir.clone(), CachedDir::Allowed(child.clone()));
444	            ignore = child;
445	        }
446	
447	        Some(self.match_path(&ignore, relative, is_dir))
448	    }
449	
450	    fn match_path(
451	        &self,
452	        ignore: &Ignore,
453	        relative: &Path,
454	        is_dir: bool,
455	    ) -> IncrementalMatch {
456	        let path = self.root.join(relative);
457	        let mut mat = IncrementalMatch::from_match(
458	            ignore.matched(&path, is_dir).map(|_| ()),
459	            is_dir,
460	        );
461	        // Whether a file is hidden or not has low precedence in filtering. We
462	        // only check it if we haven't matched anything above. This permits
463	        // callers to whitelist hidden files or directories.
464	        if self.options.hidden && mat.is_none() && is_hidden_path(&path) {
465	            mat = IncrementalMatch::ignore();
466	        }
467	        mat
468	    }
469	
470	    fn root_ignore(
471	        &mut self,
472	        errs: &mut PartialErrorBuilder,
473	    ) -> Option<Ignore> {
474	        let ignore = match self.ignore {
475	            RootIgnore::Unloaded(ref ignore) => ignore.clone(),
476	            RootIgnore::Loaded(ref ignore) => return Some(ignore.clone()),
477	            RootIgnore::NotDirectory | RootIgnore::Stdin => return None,
478	        };
479	        if !self.root.is_dir() {
480	            self.ignore = RootIgnore::NotDirectory;
481	            return None;
482	        }
483	
484	        let (parents, err) = ignore.add_parents(&self.root);
485	        errs.maybe_push(err);
486	        let (root, err) = parents.add_child(&self.root);
487	        errs.maybe_push(err);
488	        if self.shared_loaded.is_none() {
489	            self.shared_loaded = Some(root.clone());
490	        }
491	        self.ignore = RootIgnore::Loaded(root.clone());
492	        Some(root)
493	    }
494	}
495	
496	/// The result of an incremental match.
497	///
498	/// This is similar to [`Match`] in that it reports whether a file path should
499	/// be ignored, whitelisted or didn't match anything at all. It also has extra
500	/// data, such as whether a directory matched but should not be descended into.
501	///
502	/// Generally speaking, callers that only care about specific files can stick
503	/// to the `is_none()`, `is_ignore()` or `is_whitelist()` predicates. Directory
504	/// entries are more complicated because we sometimes want to yield directories
505	/// to descend into, but not actually visit (e.g., for the minimum depth
506	/// filter). Or, we may want to yield a directory to visit but not descend into
507	/// (e.g., for the maximum depth filter).
508	#[derive(Clone, Debug)]
509	pub struct IncrementalMatch {
510	    mat: Match<()>,
511	    should_descend: bool,
512	    is_within_depth: bool,
513	}
514	
515	impl IncrementalMatch {
516	    fn none(is_dir: bool) -> IncrementalMatch {
517	        IncrementalMatch {
518	            mat: Match::None,
519	            should_descend: is_dir,
520	            is_within_depth: true,
521	        }
522	    }
523	
524	    fn ignore() -> IncrementalMatch {
525	        IncrementalMatch {
526	            mat: Match::Ignore(()),
527	            should_descend: false,
528	            is_within_depth: true,
529	        }
530	    }
531	
532	    fn from_match(mat: Match<()>, is_dir: bool) -> IncrementalMatch {
533	        let should_descend = is_dir && !mat.is_ignore();
534	        IncrementalMatch { mat, should_descend, is_within_depth: true }
535	    }
536	
537	    fn no_descent(self) -> IncrementalMatch {
538	        IncrementalMatch { should_descend: false, ..self }
539	    }
540	
541	    fn not_within_depth(self) -> IncrementalMatch {
542	        IncrementalMatch { is_within_depth: false, ..self }
543	    }
544	
545	    /// Returns true if the match result didn't match anything.
546	    pub fn is_none(&self) -> bool {
547	        self.mat.is_none()
548	    }
549	
550	    /// Returns true if the match result implies the path should be ignored.
551	    pub fn is_ignore(&self) -> bool {
552	        self.mat.is_ignore()
553	    }
554	
555	    /// Returns true if the match result implies the path should be
556	    /// whitelisted.
557	    pub fn is_whitelist(&self) -> bool {
558	        self.mat.is_whitelist()
559	    }
560	
561	    /// Returns true only when this match corresponds to a directory *and*
562	    /// whether the caller should look inside this directory for additional
563	    /// results.
564	    ///
565	    /// It is possible for a match to report `false` for
566	    /// [`IncrementalMatch::is_ignore`] _and_ `false` for
567	    /// [`IncrementalMatch::should_descend`]. This can occur, for example, when
568	    /// a maximum depth setting allows a directory through, but where none of
569	    /// its children entries should be visited.
570	    ///
571	    /// This is always `false` for a file path that does *not* correspond to a
572	    /// directory.
573	    pub fn should_descend(&self) -> bool {
574	        self.should_descend
575	    }
576	
577	    /// Returns true only when this result corresponds to an entry that is
578	    /// within the depth filter.
579	    ///
580	    /// This is `false` when a path corresponds to a directory and is less than
581	    /// the minimum depth. In this case, callers should continue looking inside
582	    /// that directory.
583	    ///
584	    /// This is always `true` for a match corresponding to a file path that
585	    /// isn't a directory.
586	    pub fn is_within_depth(&self) -> bool {
587	        self.is_within_depth
588	    }
589	
590	    /// Inverts the match so that `Ignore` becomes `Whitelist` and
591	    /// `Whitelist` becomes `Ignore`. A non-match remains the same.
592	    pub fn invert(self) -> IncrementalMatch {
593	        IncrementalMatch { mat: self.mat.invert(), ..self }
594	    }
595	}
596	
597	/// Return a lexically normalized absolute representation of `path`.
598	///
599	/// This collapses `.` and `..`, but intentionally does not canonicalize or
600	/// resolve symlinks. Ignore rules apply to the lexical path, and resolving a
601	/// symlink below a root could move the result outside of that root.
602	fn normalize_absolute(path: &Path) -> Option<PathBuf> {
603	    let absolute = std::path::absolute(path).ok()?;
604	    let mut normalized = PathBuf::new();
605	    for component in absolute.components() {
606	        match component {
