188	    /// Create a new `Ignore` matcher with the parent directories of `dir`.
189	    ///
190	    /// Note that this can only be called on an `Ignore` matcher with no
191	    /// parents (i.e., `is_root` returns `true`). This will panic otherwise.
192	    pub(crate) fn add_parents<P: AsRef<Path>>(
193	        &self,
194	        path: P,
195	    ) -> (Ignore, Option<Error>) {
196	        if !self.inner.opts.parents
197	            && !self.inner.opts.git_ignore
198	            && !self.inner.opts.git_exclude
199	            && !self.inner.opts.git_global
200	        {
201	            // If we never need info from parent directories, then don't do
202	            // anything.
203	            return (self.clone(), None);
204	        }
205	        if !self.is_root() {
206	            panic!("Ignore::add_parents called on non-root matcher");
207	        }
208	        let absolute_base = match path.as_ref().canonicalize() {
209	            Ok(path) => Arc::new(path),
210	            Err(_) => {
211	                // There's not much we can do here, so just return our
212	                // existing matcher. We drop the error to be consistent
213	                // with our general pattern of ignoring I/O errors when
214	                // processing ignore files.
215	                return (self.clone(), None);
216	            }
217	        };
218	        // List of parents, from child to root.
219	        let mut parents = vec![];
220	        let mut path = &**absolute_base;
221	        while let Some(parent) = path.parent() {
222	            parents.push(parent);
223	            path = parent;
224	        }
225	        let mut errs = PartialErrorBuilder::default();
226	        let mut ig = self.clone();
227	        for parent in parents.into_iter().rev() {
228	            let mut compiled = self.inner.compiled.write().unwrap();
229	            if let Some(weak) = compiled.get(parent.as_os_str()) {
230	                if let Some(prebuilt) = weak.upgrade() {
231	                    ig = Ignore {
232	                        inner: prebuilt,
233	                        absolute_base: Some(absolute_base.clone()),
234	                    };
235	                    continue;
236	                }
237	            }
238	            let (mut igtmp, err) = ig.add_child_path(parent);
239	            errs.maybe_push(err);
240	            igtmp.is_absolute_parent = true;
241	            igtmp.has_git =
242	                if self.inner.opts.require_git && self.inner.opts.git_ignore {
243	                    parent.join(".git").exists() || parent.join(".jj").exists()
244	                } else {
245	                    false
246	                };
247	            let ig_arc = Arc::new(igtmp);
248	            ig = Ignore {
249	                inner: ig_arc.clone(),
250	                absolute_base: Some(absolute_base.clone()),
251	            };
252	            compiled.insert(
253	                parent.as_os_str().to_os_string(),
254	                Arc::downgrade(&ig_arc),
255	            );
256	        }
257	        (ig, errs.into_error_option())
258	    }
