260	    /// Return a copy of this matcher with a fresh, empty cache of compiled
261	    /// parent directory matchers.
262	    ///
263	    /// The returned matcher shares this matcher's configuration and already
264	    /// compiled matchers, but parent directory matchers compiled from here
265	    /// on are neither read from nor written to the cache shared with other
266	    /// matchers derived from the same builder. This permits reloading ignore
267	    /// rules from disk for one matcher without affecting any other matcher.
268	    pub(crate) fn refresh(&self) -> Ignore {
269	        let mut inner = (*self.inner).clone();
270	        inner.compiled = Arc::new(RwLock::new(HashMap::new()));
271	        Ignore {
272	            inner: Arc::new(inner),
273	            absolute_base: self.absolute_base.clone(),
274	        }
275	    }
