278	    ///
279	    /// Since building the matcher may require reading from multiple
280	    /// files, it's possible that this method partially succeeds. Therefore,
281	    /// a matcher is always returned (which may match nothing) and an error is
282	    /// returned if it exists.
283	    ///
284	    /// Note that all I/O errors are completely ignored.
285	    pub(crate) fn add_child<P: AsRef<Path>>(
286	        &self,
287	        dir: P,
288	    ) -> (Ignore, Option<Error>) {
289	        let (ig, err) = self.add_child_path(dir.as_ref());
290	        (
291	            Ignore {
292	                inner: Arc::new(ig),
293	                absolute_base: self.absolute_base.clone(),
294	            },
295	            err,
296	        )
297	    }
