299	    /// Like add_child, but uses successful read_dir entries to reduce
300	    /// probing when discovering ignore files.
301	    pub(crate) fn add_child_with_entries<P: AsRef<Path>>(
302	        &self,
303	        dir: P,
304	        entries: &[fs::DirEntry],
305	    ) -> (Ignore, Option<Error>) {
306	        let files = self.collect_ignore_files(entries);
307	        let (ig, err) = self.add_child_path_with_found_ignore_files(
308	            dir.as_ref(),
309	            Some(&files),
310	        );
311	        (
312	            Ignore {
313	                inner: Arc::new(ig),
314	                absolute_base: self.absolute_base.clone(),
315	            },
316	            err,
317	        )
318	    }
