486	    /// Returns true if at least one type of ignore rule should be matched.
487	    fn has_any_ignore_rules(&self) -> bool {
488	        let opts = self.inner.opts;
489	        let has_custom_ignore_files =
490	            !self.inner.custom_ignore_filenames.is_empty();
491	        let has_explicit_ignores = !self.inner.explicit_ignores.is_empty();
492	
493	        opts.ignore
494	            || opts.git_global
495	            || opts.git_ignore
496	            || opts.git_exclude
497	            || has_custom_ignore_files
498	            || has_explicit_ignores
499	    }
