830	    /// Builds a new `Ignore` matcher using the given CWD directory.
831	    ///
832	    /// The matcher returned won't match anything until ignore rules from
833	    /// directories are added to it.
834	    pub(crate) fn build_with_cwd(&self, cwd: Option<PathBuf>) -> Ignore {
835	        let global_gitignores_relative_to =
836	            cwd.or_else(|| self.global_gitignores_relative_to.clone());
837	        let git_global_matcher = if !self.opts.git_global {
838	            Gitignore::empty()
839	        } else if let Some(ref cwd) = global_gitignores_relative_to {
840	            let mut builder = GitignoreBuilder::new(cwd);
841	            builder
842	                .case_insensitive(self.opts.ignore_case_insensitive)
843	                .unwrap();
844	            let (gi, err) = builder.build_global();
845	            if let Some(err) = err {
846	                log::debug!("{}", err);
847	            }
848	            gi
849	        } else {
850	            log::debug!(
851	                "ignoring global gitignore file because CWD is not known"
852	            );
853	            Gitignore::empty()
854	        };
855	
856	        Ignore {
857	            inner: Arc::new(IgnoreInner {
858	                compiled: Arc::new(RwLock::new(HashMap::new())),
859	                dir: self.dir.clone(),
860	                overrides: self.overrides.clone(),
861	                types: self.types.clone(),
862	                parent: None,
863	                is_absolute_parent: true,
864	                global_gitignores_relative_to,
865	                explicit_ignores: Arc::new(self.explicit_ignores.clone()),
866	                custom_ignore_filenames: Arc::new(
867	                    self.custom_ignore_filenames.clone(),
868	                ),
869	                custom_ignore_matcher: Gitignore::empty(),
870	                ignore_matcher: Gitignore::empty(),
871	                git_global_matcher: Arc::new(git_global_matcher),
872	                git_ignore_matcher: Gitignore::empty(),
873	                git_exclude_matcher: Gitignore::empty(),
874	                has_git: false,
875	                opts: self.opts,
876	            }),
877	            absolute_base: None,
878	        }
879	    }
