66	/// Represents an error that can occur when parsing a gitignore file.
67	#[derive(Debug)]
68	pub enum Error {
69	    /// A collection of "soft" errors. These occur when adding an ignore
70	    /// file partially succeeded.
71	    Partial(Vec<Error>),
72	    /// An error associated with a specific line number.
73	    WithLineNumber {
74	        /// The line number.
75	        line: u64,
76	        /// The underlying error.
77	        err: Box<Error>,
78	    },
79	    /// An error associated with a particular file path.
80	    WithPath {
81	        /// The file path.
82	        path: PathBuf,
83	        /// The underlying error.
84	        err: Box<Error>,
85	    },
86	    /// An error associated with a particular directory depth when recursively
87	    /// walking a directory.
88	    WithDepth {
89	        /// The directory depth.
90	        depth: usize,
91	        /// The underlying error.
92	        err: Box<Error>,
93	    },
94	    /// An error that occurs when a file loop is detected when traversing
95	    /// symbolic links.
96	    Loop {
97	        /// The ancestor file path in the loop.
98	        ancestor: PathBuf,
99	        /// The child file path in the loop.
100	        child: PathBuf,
101	    },
102	    /// An error that occurs when doing I/O, such as reading an ignore file.
103	    Io(std::io::Error),
104	    /// An error that occurs when trying to parse a glob.
105	    Glob {
106	        /// The original glob that caused this error. This glob, when
107	        /// available, always corresponds to the glob provided by an end user.
108	        /// e.g., It is the glob as written in a `.gitignore` file.
109	        ///
110	        /// (This glob may be distinct from the glob that is actually
111	        /// compiled, after accounting for `gitignore` semantics.)
112	        glob: Option<String>,
113	        /// The underlying glob error as a string.
114	        err: String,
115	    },
116	    /// A type selection for a file type that is not defined.
117	    UnrecognizedFileType(String),
118	    /// A user specified file type definition could not be parsed.
119	    InvalidDefinition,
120	}
121	
122	impl Clone for Error {
123	    fn clone(&self) -> Error {
124	        match *self {
125	            Error::Partial(ref errs) => Error::Partial(errs.clone()),
126	            Error::WithLineNumber { line, ref err } => {
127	                Error::WithLineNumber { line, err: err.clone() }
128	            }
129	            Error::WithPath { ref path, ref err } => {
130	                Error::WithPath { path: path.clone(), err: err.clone() }
131	            }
132	            Error::WithDepth { depth, ref err } => {
133	                Error::WithDepth { depth, err: err.clone() }
134	            }
135	            Error::Loop { ref ancestor, ref child } => Error::Loop {
136	                ancestor: ancestor.clone(),
137	                child: child.clone(),
138	            },
139	            Error::Io(ref err) => match err.raw_os_error() {
140	                Some(e) => Error::Io(std::io::Error::from_raw_os_error(e)),
141	                None => {
142	                    Error::Io(std::io::Error::new(err.kind(), err.to_string()))
143	                }
144	            },
145	            Error::Glob { ref glob, ref err } => {
146	                Error::Glob { glob: glob.clone(), err: err.clone() }
147	            }
148	            Error::UnrecognizedFileType(ref err) => {
149	                Error::UnrecognizedFileType(err.clone())
150	            }
151	            Error::InvalidDefinition => Error::InvalidDefinition,
152	        }
153	    }
154	}
155	
156	impl Error {
157	    /// Returns true if this is a partial error.
158	    ///
159	    /// A partial error occurs when only some operations failed while others
160	    /// may have succeeded. For example, an ignore file may contain an invalid
161	    /// glob among otherwise valid globs.
162	    pub fn is_partial(&self) -> bool {
163	        match *self {
164	            Error::Partial(_) => true,
165	            Error::WithLineNumber { ref err, .. } => err.is_partial(),
166	            Error::WithPath { ref err, .. } => err.is_partial(),
167	            Error::WithDepth { ref err, .. } => err.is_partial(),
168	            _ => false,
169	        }
170	    }
171	
172	    /// Returns true if this error is exclusively an I/O error.
173	    pub fn is_io(&self) -> bool {
174	        match *self {
175	            Error::Partial(ref errs) => errs.len() == 1 && errs[0].is_io(),
176	            Error::WithLineNumber { ref err, .. } => err.is_io(),
177	            Error::WithPath { ref err, .. } => err.is_io(),
178	            Error::WithDepth { ref err, .. } => err.is_io(),
179	            Error::Loop { .. } => false,
180	            Error::Io(_) => true,
181	            Error::Glob { .. } => false,
182	            Error::UnrecognizedFileType(_) => false,
183	            Error::InvalidDefinition => false,
184	        }
185	    }
186	
187	    /// Inspect the original [`std::io::Error`] if there is one.
188	    ///
