    /// Reload ignore rules from disk for one directory and its descendants.
    ///
    /// ... (docs)
    pub fn refresh_dir<P: AsRef<Path>>(
        &mut self,
        dir: P,
    ) -> Result<(), Error> {
        // Normalize the directory path, ignoring `.` components. Absolute
        // paths and paths with `..` components are rejected without
        // changing any matching state.
        let mut normalized = PathBuf::new();
        for component in dir.as_ref().components() {
            match component {
                std::path::Component::CurDir => {}
                std::path::Component::Normal(c) => normalized.push(c),
                std::path::Component::ParentDir
                | std::path::Component::RootDir
                | std::path::Component::Prefix(_) => {
                    return Err(Error::Io(std::io::Error::new(
                        std::io::ErrorKind::InvalidInput,
                        format!(
                            "refresh directory must be relative to the \
                             search root without `..` components: {:?}",
                            dir.as_ref(),
                        ),
                    )));
                }
            }
        }
        if matches!(self.ignore, RootIgnore::Stdin) {
            return Ok(());
        }
        // The empty path (or a lone `.`) designates the search root, which
        // is exactly what a full refresh reloads.
        if normalized.as_os_str().is_empty() {
            self.refresh();
            return Ok(());
        }
        // Drop every cached decision at or below the directory. The cached
        // matchers above it are retained, so queries re-read the ignore
        // files in the directory and its descendants lazily, while rules
        // loaded from directories above it keep their current versions.
        self.dirs.retain(|dir_path, _| !dir_path.starts_with(&normalized));
        Ok(())
    }
